// Writes the Web client's settings from samples/.env into a TypeScript file
// the app imports. Only FLUXGATE_WEB_* values are copied: they are meant for
// the browser. The generated file is git-ignored.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';

const envFile = new URL('../../.env', import.meta.url);
const values = {};
if (existsSync(envFile)) {
  for (const line of readFileSync(envFile, 'utf8').split('\n')) {
    const match = /^(FLUXGATE_WEB_[A-Z_]+)=(.*)$/.exec(line.trim());
    if (match) {
      values[match[1]] = match[2];
    }
  }
}
const settings = {
  baseUrl: process.env.FLUXGATE_WEB_BASE_URL || values.FLUXGATE_WEB_BASE_URL || 'http://localhost:28081',
  sdkKey: process.env.FLUXGATE_WEB_SDK_KEY || values.FLUXGATE_WEB_SDK_KEY || '',
};
writeFileSync(
  new URL('../src/environments/fluxgate.generated.ts', import.meta.url),
  `// Generated by scripts/write-env.mjs from samples/.env. Do not edit or commit.\n` +
    `export const fluxgateSettings = ${JSON.stringify(settings, null, 2)};\n`,
);
